// A service's own mark, from `src/connect/brandIcons.ts` (generated by
// scripts/gen-brand-icons.mjs off each provider's published favicon).
//
// Every mark sits on the same light plate. Favicons are drawn for a browser
// tab, so they assume a light background: GitHub's is a near-black octocat on
// transparent, which would vanish into a dark widget surface. A plate also
// makes a row of them read as one set even though they arrive at different
// sizes, paddings and shapes. [S-47]
import type { JSX } from 'solid-js';
import { BRAND_ICONS, brandIconSrc, type BrandIconKey } from '../connect/brandIcons.ts';
import './BrandMark.css';

export function BrandMark(props: { brand: BrandIconKey; class?: string }): JSX.Element {
  const icon = () => BRAND_ICONS[props.brand];
  return (
    <span class={`brand-plate${props.class ? ` ${props.class}` : ''}`} title={icon().title}>
      {/* Decorative: the tile always carries the brand's name as text beside
          it, so an alt would be read out twice. */}
      <img class="brand-mark" src={brandIconSrc(icon())} alt="" draggable={false} />
    </span>
  );
}
